930	// Resolve matches a validated request against a validated configuration and
931	// computes the upstream URL. Failure codes are route_not_found and
932	// route_conflict.
933	func Resolve(cfg *Config, req *Request) (*Resolution, *Failure) {
934		path := req.Target
935		if i := strings.IndexByte(path, '?'); i >= 0 {
936			path = path[:i]
937		}
938	
939		type candidate struct {
940			route    *Route
941			concrete bool
942		}
943		var matched []candidate
944		for i := range cfg.Routes {
945			route := &cfg.Routes[i]
946			concrete, wildcard := methodMatch(route.Methods, req.Method)
947			if !concrete && !wildcard {
948				continue
949			}
950			if !prefixMatch(route.PathPrefix, path) {
951				continue
952			}
953			matched = append(matched, candidate{route, concrete})
954		}
955		if len(matched) == 0 {
956			return nil, failuref("route_not_found", "no route matches %s %s", req.Method, path)
957		}
958	
959		// Longest prefix wins.
960		bestLen := 0
961		for _, c := range matched {
962			if n := len(c.route.PathPrefix); n > bestLen {
963				bestLen = n
964			}
965		}
966		winners := matched[:0]
967		for _, c := range matched {
968			if len(c.route.PathPrefix) == bestLen {
969				winners = append(winners, c)
970			}
971		}
972	
973		// Among equal prefixes a concrete method beats the wildcard.
974		var concrete []candidate
975		for _, c := range winners {
976			if c.concrete {
977				concrete = append(concrete, c)
978			}
979		}
980		if len(concrete) > 0 {
981			winners = concrete
982		}
983		if len(winners) > 1 {
984			ids := make([]string, 0, len(winners))
985			for _, c := range winners {
986				ids = append(ids, c.route.ID)
987			}
988			sort.Strings(ids)
989			f := failuref("route_conflict", "multiple routes match %s %s", req.Method, path)
990			f.Candidates = ids
991			return nil, f
992		}
993	
994		upstreamURL, f := joinUpstream(winners[0].route, path, req.Target)
995		if f != nil {
996			return nil, f
997		}
998		return &Resolution{RouteID: winners[0].route.ID, UpstreamURL: upstreamURL}, nil
999	}
1000	
1001	// methodMatch reports whether the method list matches the request method
1002	// concretely (an exact, case-sensitive entry) or via the "*" wildcard.
1003	func methodMatch(methods []string, method string) (concrete, wildcard bool) {
1004		for _, m := range methods {
1005			switch {
1006			case m == "*":
1007				wildcard = true
1008			case m == method:
1009				concrete = true
1010			}
1011		}
1012		return concrete, wildcard
1013	}
1014	
1015	// prefixMatch matches raw encoded paths on segment boundaries: "%2F" is never
1016	// treated as a separator and the root prefix matches every origin-path.
1017	func prefixMatch(prefix, path string) bool {
1018		if prefix == "/" {
1019			return true
1020		}
1021		if path == prefix {
1022			return true
1023		}
1024		return strings.HasPrefix(path, prefix) && path[len(prefix)] == '/'
1025	}
1026	
1027	// joinUpstream strips the route prefix from the request path and joins the
1028	// remainder onto the upstream base path with exactly one slash at the
1029	// junction. The junction is one run of literal slashes: every trailing
1030	// slash on the base path and every leading slash on the remainder are
1031	// merged into that single slash, even when either side contributes
1032	// several. Nothing else is normalized: slashes inside either part, the
1033	// remainder's trailing slashes (once non-slash content has appeared),
1034	// ".", ".." and percent escapes such as "%2F" are carried over byte for
1035	// byte, never decoded first. The base path is sliced out of the raw
1036	// upstream so joining never re-encodes, reorders or drops anything
1037	// outside the junction. The raw query is preserved verbatim unless the
1038	// route defines queryTransforms, in which case they rewrite it after
1039	// route selection.
1040	func joinUpstream(route *Route, path, target string) (string, *Failure) {
1041		if _, err := url.Parse(route.Upstream); err != nil {
1042			// Config validation already rejected this.
1043			return "", failuref("invalid_config", "route %q has an invalid upstream: %v", route.ID, err)
1044		}
1045	
1046		var remainder string
1047		switch {
1048		case route.PathPrefix == "/":
1049			// Root keeps the whole following path; "/" itself has an empty remainder.
1050			if path != "/" {
1051				remainder = path
1052			}
1053		default:
1054			remainder = path[len(route.PathPrefix):] // "" or "/...", boundary is a literal slash
1055		}
1056	
1057		// Slice the validated upstream raw so nothing outside the junction is
1058		// normalized or re-escaped. The address boundaries come from the same
1059		// splitUpstream reading the host validators used (scheme://authority
1060		// followed by the base path), so joining can never split userinfo, the
1061		// IPv6 brackets, the port or the base path differently than validation.
1062		parts := splitUpstream(route.Upstream)
1063		basePath := parts.basePath
1064	
1065		// Collapse only the junction run: all trailing slashes of the base
1066		// path meet all leading slashes of the remainder, and the junction
1067		// keeps exactly one slash whether or not anything follows them. A
1068		// remainder made entirely of slashes has no content past the run, so
1069		// it likewise ends in that single slash.
1070		baseTrimmed := strings.TrimRight(basePath, "/")
1071		rest := strings.TrimLeft(remainder, "/")
1072		joined := baseTrimmed + "/" + rest
1073	
1074		result := route.Upstream[:parts.schemeEnd+3] + parts.authority + joined
1075		query, f := applyQueryTransforms(route.QueryTransforms, target)
1076		if f != nil {
1077			return "", f
1078		}
1079		return result + query, nil
1080	}
1081	
1082	// isToken reports whether s is an RFC 7230 token, i.e. a legal HTTP method.
1083	func isToken(s string) bool {
1084		if s == "" {
1085			return false
1086		}
1087		for i := 0; i < len(s); i++ {
1088			if !isTokenChar(s[i]) {
1089				return false
1090			}
1091		}
1092		return true
1093	}
1094	
1095	func isTokenChar(c byte) bool {
1096		switch {
1097		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
1098			return true
1099		}
1100		switch c {
1101		case '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~':
1102			return true
1103		}
1104		return false
1105	}
1106	
1107	// validPercentEscapes checks that every "%' is followed by two hex digits.
1108	// Matching and joining stay on raw strings, but malformed escapes are rejected
1109	// up front for both prefixes and request targets.
1110	func validPercentEscapes(s string) bool {
1111		for i := 0; i < len(s); i++ {
1112			if s[i] != '%' {
1113				continue
1114			}
1115			if i+2 >= len(s) || !isHex(s[i+1]) || !isHex(s[i+2]) {
1116				return false
1117			}
1118			i += 2
1119		}
1120		return true
1121	}
1122	
1123	func isHex(c byte) bool {
1124		switch {
1125		case c >= '0' && c <= '9', c >= 'a' && c <= 'f', c >= 'A' && c <= 'F':
1126			return true
1127		}
1128		return false
1129	}
